    // This handles cases where H1 might have "TICKET:" prefix but title doesn't, or vice versa
    if (h1Text === titleLower || 
        h1Text.includes(titleLower) || 
        titleLower.includes(h1Text) ||
        // Also check if they match after removing common prefixes
        h1Text.replace(/^(ticket[-:]?\s*)/i, '') === titleLower.replace(/^(ticket[-:]?\s*)/i, '') ||
        h1Text.replace(/^(ticket[-:]?\s*)/i, '').includes(titleLower.replace(/^(ticket[-:]?\s*)/i, ''))) {
      // Remove the first H1 line and any trailing newlines
      content = content.replace(/^#\s+.+$/m, '').trim();
    }
  }
}

// Remove User Story section if it exists (we display it separately above)
content = content.replace(/^##\s+User Story\s*\n[\s\S]*?(?=\n##|\n---|$)/i, '').trim();
